using System.Collections.Generic;

namespace QLB.Info
{
    public class FlightAnalyticsRequest { public string FromDate { get; set; } public string ToDate { get; set; } public string Airport { get; set; } public string Oper { get; set; } public string Purpose { get; set; } public bool CurrentDay { get; set; } public string Period { get; set; } }
    public class FlightAnalyticsRow { public string Callsign { get; set; } public string Oper { get; set; } public string Registration { get; set; } public string PermType { get; set; } public string FromAirp { get; set; } public string ToAirp { get; set; } public string AtdDay { get; set; } public string AtaDay { get; set; } public string EobtDay { get; set; } public string Status { get; set; } public string FlightDate { get; set; } public string CraftType { get; set; } public string Route { get; set; } public string PermitNbr { get; set; } public string Category { get; set; } }
    public class AirportTrafficRow { public string Code { get; set; } public int Departures { get; set; } public int Arrivals { get; set; } public int Total { get; set; } }
    public class FlightStatusRateResponse { public string Source { get; set; } public int Total { get; set; } public int Finished { get; set; } public int Cancel { get; set; } public int Delay { get; set; } public int Wait { get; set; } public List<FlightAnalyticsRow> Flights { get; set; } }
