    public class FlightTrendResponse { public string Source { get; set; } public string Period { get; set; } public string CurrentFrom { get; set; } public string CurrentTo { get; set; } public string PreviousFrom { get; set; } public string PreviousTo { get; set; } public int CurrentTotal { get; set; } public int PreviousTotal { get; set; } public int CurrentFinished { get; set; } public int CurrentDelay { get; set; } public int Difference { get; set; } public double ChangePercent { get; set; } public List<string> Labels { get; set; } public List<int> Current { get; set; } public List<int> Previous { get; set; } }
